from collections import deque, Counter

def comps(mat, pred=lambda x:x!=8):
 h=len(mat); w=len(mat[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen or not pred(mat[r][c]): continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    y,x=q.pop();cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and pred(mat[yy][xx]):
      seen.add((yy,xx));q.append((yy,xx))
   out.append(cells)
 return out
